export function resolvePlaylistItem(data:Item,playlist:Item,placement:Item):Item {
  const current=(data.content||[]).find((c:Item)=>c.id===placement.contentId);
  if(!current)return {id:placement.contentId,title:'Ontbrekende content',family:'free',settings:{previewState:'error'}};
  const historical=placement.revision&&placement.revision!==current.revision?(current.versions||[]).find((v:Item)=>v.revision===placement.revision)?.snapshot:null;
  const source=clone(historical||current),themeId=placement.theme&&placement.theme!=='inherit'?placement.theme:playlist.theme||source.theme||data.settings?.defaultTheme;
  const theme=(data.themes||[]).find((t:Item)=>t.id===themeId);
  const themed=theme?withTheme(source,theme):source;
  return {...themed,orientation:playlist.orientation||source.orientation,placement:clone(placement)};
}
