  const live=items.filter(i=>i.status!=='archived'),processing=live.filter(i=>i.status==='processing').length;
  const impact=(id:string)=>(data.playlists||[]).filter((p:any)=>(p.items||p.slides||[]).some((i:any)=>i.contentId===id||i.id===id||i===id));
  function create(family:string,template?:Item){let item=defaults(family);const theme=(data.themes||[]).find((t:any)=>t.id===(data.settings?.defaultTheme||item.theme));if(theme)item=withTheme(item,theme);if(template)item=withTemplate(item,template);update((d:any)=>{d.content.unshift(item)});setNewOpen(false);go('studio',item.id)}
  function toggle(id:string){setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id])}
  function archive(item:Item){update((d:any)=>{const target=d.content.find((i:any)=>i.id===item.id);target.status=target.status==='archived'?'draft':'archived'});setArchiveItem(null);setSelected(s=>s.filter(id=>id!==item.id));toast(item.status==='archived'?'Ontwerp teruggezet in de bibliotheek.':'Gearchiveerd. Gepubliceerde scherminhoud blijft behouden.')}
  function duplicate(item:Item){const duplicate={...clone(item),id:crypto.randomUUID(),title:`${item.title} · kopie`,status:'draft',revision:1,versions:[]};update((d:any)=>{d.content.unshift(duplicate)});toast('Kopie toegevoegd aan de bibliotheek.')}
  function retry(item:Item){update((d:any)=>{d.content.find((i:any)=>i.id===item.id).status='processing'});setTimeout(()=>update((d:any)=>{const row=d.content.find((i:any)=>i.id===item.id);if(row)row.status='ready'}),1500)}
  async function upload(files:FileList|null){if(!files?.length)return;setUploading(true);for(const file of Array.from(files)){if(!/^(image|video)\//.test(file.type)){toast(`${file.name}: kies een afbeelding of video.`);continue}if(file.size>4*1024*1024){toast(`${file.name}: gebruik voor deze lokale demo een bestand kleiner dan 4 MB.`);continue}const url=await new Promise<string>((resolve)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.readAsDataURL(file)});const item:Item={...defaults('free'),title:file.name.replace(/\.[^.]+$/,''),type:'media',source:'Upload',status:'processing',settings:{mediaUrl:url,mediaKind:file.type.startsWith('video')?'video':'image',fileName:file.name,fileSize:file.size}};update((d:any)=>d.content.unshift(item));setTimeout(()=>update((d:any)=>{const target=d.content.find((i:any)=>i.id===item.id);if(target)target.status='ready'}),1800)}setUploading(false);if(fileInput.current)fileInput.current.value=''}
